const chunks = [];
for await (const chunk of process.stdin) {
  chunks.push(chunk);
}
const input = Buffer.concat(chunks).toString('utf8').trim();
const n = parseInt(input, 10);
if (Number.isInteger(n) && n > 0) {
  process.stdout.write(JSON.stringify({ quantity: n }));
} else {
  process.stdout.write(JSON.stringify({ error: 'invalid_quantity' }));
}

const chunks = [];
for await (const chunk of process.stdin) {
  chunks.push(chunk);
}
const input = Buffer.concat(chunks).toString('utf8').trim();
if (/^\d+$/.test(input)) {
  const n = parseInt(input, 10);
  if (Number.isInteger(n) && n > 0) {
    process.stdout.write(JSON.stringify({ quantity: n }) + '\n');
  } else {
    process.stdout.write(JSON.stringify({ error: 'invalid_quantity' }) + '\n');
  }
} else {
  process.stdout.write(JSON.stringify({ error: 'invalid_quantity' }) + '\n');
}

